import { useState } from "react";
import { Card } from "@/shared/ui/data/Card";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";

// Vendored from `../lib/appearance` (unresolvable in this sandbox) — unchanged.
const ACCENT_PRESETS = [
  { id: "amber", label: "Amber", hue: 70 },
  { id: "blue", label: "Blue", hue: 230 },
  { id: "green", label: "Green", hue: 145 },
  { id: "cyan", label: "Cyan", hue: 195 },
  { id: "purple", label: "Purple", hue: 300 },
  { id: "red", label: "Red", hue: 25 },
];
const DEFAULT_ACCENT = "amber";
function accentVars(id) {
  const p = ACCENT_PRESETS.find((x) => x.id === id) ?? ACCENT_PRESETS.find((x) => x.id === DEFAULT_ACCENT);
  return { accent: `oklch(0.80 0.14 ${p.hue})`, accentDim: `oklch(0.55 0.10 ${p.hue})` };
}

// Preview-only stand-in for `useAppStore().accent` / `setAccent` (app-internal, unresolvable here).
export function AccentColorCard() {
  const [accent, setAccent] = useState(DEFAULT_ACCENT);

  return (
    <Card title="Accent color" hint="the highlight color used across the app">
      <Row gap={10} align="stretch" wrap>
        {ACCENT_PRESETS.map((p) => {
          const on = p.id === accent;
          const { accent: color } = accentVars(p.id);
          return (
            // eslint-disable-next-line no-restricted-syntax -- bespoke color-swatch pill (radius 99, per-preset accent bg/box-shadow); not the .btn family, SegmentedControl can't reproduce the swatch
            <button
              key={p.id}
              className="mono"
              aria-label={p.label}
              aria-pressed={on}
              title={p.label}
              onClick={() => setAccent(p.id)}
              style={{
                display: "flex", alignItems: "center", gap: 8,
                padding: "6px 12px 6px 8px", borderRadius: 99, cursor: "pointer",
                background: on ? "var(--bg-elev2)" : "var(--bg-elev)",
                border: "1px solid " + (on ? "var(--accent-dim)" : "var(--border-soft)"),
                fontSize: 11,
                color: on ? "var(--fg)" : "var(--fg-muted)",
              }}
            >
              <Box as="span" bg={color} style={{
                width: 16, height: 16, borderRadius: "50%",
                boxShadow: on ? "0 0 0 2px var(--bg-elev2), 0 0 0 3px " + color : "none",
              }} />
              {p.label}
            </button>
          );
        })}
      </Row>
    </Card>
  );
}
